using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using SargasPC;
class WorkflowTests {
 static int n;static void Check(bool v){n++;if(!v)throw new Exception("Workflow case "+n);}static void Reject(Action a){bool failed=false;try{a();}catch{failed=true;}Check(failed);}
 static void Main(string[] args){string root=Path.Combine(args[0],"workflow-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string files=Path.Combine(root,"files");Directory.CreateDirectory(files);for(int i=0;i<35;i++)File.WriteAllText(Path.Combine(files,"file"+i+".txt"),"abc");var c=new Core(Path.Combine(root,"data"));c.Folder(files);string plan=Path.Combine(c.Root,"folder-plan.json");var q=Data.Read<FolderPlan>(plan,6000000);Check(q.Done==32&&q.Pending.Count==3);Check(c.ReadBytes==96&&c.NotChecked==3);Check(!c.Outcome(true).Contains("UŽBAIGTAS"));var restarted=new Core(c.Root);restarted.ContinueFolder(1);q=Data.Read<FolderPlan>(plan,6000000);Check(q.Done==33&&q.Pending.Count==2);Check(restarted.ReadBytes==3);File.Delete(q.Pending[0]);restarted.Reset();restarted.ContinueFolder(2);q=Data.Read<FolderPlan>(plan,6000000);Check(q.Done==34&&q.Pending.Count==1);Check(restarted.NotChecked==1);string before=File.ReadAllText(plan);restarted.Cancelled=true;Reject(()=>restarted.ContinueFolder());Check(File.ReadAllText(plan)==before);restarted.Reset();File.WriteAllText(q.Pending[0],"changed");restarted.ContinueFolder(1);q=Data.Read<FolderPlan>(plan,6000000);Check(q.Done==35&&q.Pending.Count==0);Check(restarted.NotChecked==0);Check(restarted.ReadBytes==7);
  restarted.Reset();c.Folder(files);string list=Path.Combine(root,"hashes");File.WriteAllText(list,Data.Digest(Encoding.ASCII.GetBytes("abc")));restarted.Import(list);before=File.ReadAllText(plan);Reject(()=>restarted.ContinueFolder());Check(File.ReadAllText(plan)==before);Check(restarted.Config.ImportAt>0);
  Data.Atomic(plan,"invalid");Reject(()=>restarted.ContinueFolder());Check(File.ReadAllText(plan)=="invalid");q.Pending=new List<string>{Path.Combine(root,"outside")};Data.Atomic(plan,Data.Json().Serialize(q));before=File.ReadAllText(plan);Reject(()=>restarted.ContinueFolder());Check(File.ReadAllText(plan)==before);
  var w=new Witness {Test=true,Size=68};Reject(()=>restarted.Isolate(w,true));Check(!Directory.GetFiles(Path.Combine(restarted.Root,"vault")).Any());string eicar="X5O!P%@AP[4\\PZX54(P^)7CC)7}$EICAR-"+"STANDARD-ANTIVIRUS-TEST-FILE!$H+H*";string test=Path.Combine(files,"test.txt");File.WriteAllText(test,eicar);var witness=restarted.Scan(test);restarted.Reset();restarted.Describe(witness,new HashSet<string>{witness.Hash});Check(witness.Kind=="TEST"&&restarted.TestFindings==1&&restarted.HashFindings==0);Check(restarted.Outcome(true).Contains("ne tikras virusas"));restarted.Reset();witness=restarted.Scan(Path.Combine(files,"file0.txt"));restarted.Describe(witness,restarted.Database());Check(witness.Kind=="HASH"&&restarted.HashFindings==1);Check(restarted.ReadBytes==3);
  restarted.Reset();restarted.Paused=true;var wait=Task.Run(()=>restarted.Check());Thread.Sleep(150);restarted.Paused=false;Check(wait.Wait(2000));Check(restarted.PausedMs>=100);restarted.SaveLast("completed");Check(new Core(restarted.Root).LastOperation().Contains("completed"));Check(restarted.Dashboard().Contains("reikia paleisti"));restarted.Config.SelfPassed=true;restarted.Config.SelfAt=DateTime.UtcNow.Ticks;restarted.Config.SelfVersion=49;Check(restarted.Dashboard().Contains("praėjo šiame"));restarted.Config.SelfAt=DateTime.UtcNow.AddDays(1).Ticks;Check(restarted.Dashboard().Contains("reikia paleisti"));restarted.Config.SelfAt=DateTime.UtcNow.Ticks;restarted.Config.SelfVersion=13;Check(restarted.Dashboard().Contains("reikia paleisti"));
  var row=new Dictionary<string,object>{{"status","ready"},{"engine","ClamAV test"},{"database_version",123},{"database_time",DateTimeOffset.UtcNow.ToString("o")}};Core.ValidateHealth(row,DateTimeOffset.UtcNow);Check(true);row["database_time"]=DateTimeOffset.UtcNow.AddDays(-8).ToString("o");Reject(()=>Core.ValidateHealth(row,DateTimeOffset.UtcNow));row["database_time"]=DateTimeOffset.UtcNow.AddMinutes(10).ToString("o");Reject(()=>Core.ValidateHealth(row,DateTimeOffset.UtcNow));row["database_time"]=DateTimeOffset.UtcNow.ToString("o");row["database_version"]=0;Reject(()=>Core.ValidateHealth(row,DateTimeOffset.UtcNow));row["database_version"]=1;row["status"]="failed";Reject(()=>Core.ValidateHealth(row,DateTimeOffset.UtcNow));
  row["status"]="ready";row["database_time"]="2026-10-19T12:00:00";Reject(()=>Core.ValidateHealth(row,DateTimeOffset.UtcNow));
  restarted.Reset();witness=restarted.Scan(Path.Combine(files,"file0.txt"));restarted.Describe(witness,new System.Collections.Generic.HashSet<string>{witness.Hash});Check(restarted.SessionFindings.Count==1);restarted.Describe(witness,new System.Collections.Generic.HashSet<string>{witness.Hash});Check(restarted.SessionFindings.Count==1);File.WriteAllText(witness.Path,"replacement");Reject(()=>restarted.Verify(witness));restarted.Reset();Check(restarted.SessionFindings.Count==0);Check(new Settings().Motion);restarted.Config.Motion=false;restarted.SaveSettings();Check(!new Core(restarted.Root).Config.Motion);
  Console.WriteLine("PC WorkflowTests: "+n+" checks passed (host only; no native Windows / real server).");}finally{Directory.Delete(root,true);}}
}
